// One DLL, every build: demo, Playtest, and the full game.
// Two failure classes to defend against:
//   1. Method signature changes  -> use name-only Harmony targets + reflection invoke.
//   2. Member-shape changes      -> use build-tolerant accessors (field OR property).

using System.Reflection;
using CUCoreLib.Helpers;
using HarmonyLib;
using UnityEngine;

// --- Build detection (cached, shared seam) -------------------------------
// CUCoreUtils.IsDemo() scans for full-game-only types; needs 2+ matches to
// declare the full game, so one same-named modded type won't fool it.
public static class BuildGate
{
    public static void LogBuild()
    {
        if (GameBuildInfo.IsFullGame)
            Plugin.Logger.LogInfo("Running the full game.");
        else
            Plugin.Logger.LogInfo("Running the demo.");
    }
}

// Gate a whole Harmony family to one build. Skipped before targets resolve,
// so full-game-only patches never throw on the demo.
[AppliesToBuild(GameBuild.Full)]
[HarmonyPatch(typeof(Body), "SomeFullGameOnlyMethod")]
public static class FullGameOnlyPatch
{
    [HarmonyPostfix]
    private static void Postfix() { }
}

// --- Signature change: Body.Eat(float,float) -> Eat(float,float,int) -----
// Name-only target binds to whichever single Eat overload exists at runtime.
internal static class BodyEat
{
    private static readonly MethodInfo EatMethod = AccessTools.Method(typeof(Body), "Eat");
    private static readonly bool HasFoodType =
        EatMethod != null && EatMethod.GetParameters().Length >= 3;

    // foodType: 0 = neutral, 1 = half-hunger + sickness, 2 = vomit and refuse.
    internal static void Invoke(Body body, float hungerAmount, float weightGain, int foodType)
    {
        if (body == null || EatMethod == null) return;
        var args = HasFoodType
            ? new object[] { hungerAmount, weightGain, foodType }
            : new object[] { hungerAmount, weightGain };
        EatMethod.Invoke(body, args); // still runs your prefix/postfix chain
    }
}

[HarmonyPatch(typeof(Body), "Eat")] // no arg types -> survives the signature change
public static class InfiniteSteakPatch
{
    [HarmonyPostfix]
    private static void Postfix(Body __instance)
    {
        BodyEat.Invoke(__instance, 15f, 1.6f, 1);
    }
}

// --- Member-shape change: BuildingEntity.health field -> property --------
// Direct .health emits ldfld/stfld and throws MissingFieldException on the
// full game, often inside a Harmony DMD for BuildingEntity.Update.
// CUCoreLib's accessor resolves field-or-property once and caches delegates.
public static class BuildingHealthExample
{
    public static void Damage(BuildingEntity building, float amount)
    {
        if (building == null) return;
        building.SetHealth(building.GetHealth() - amount);
        // On the full game the setter runs CheckDamage(); it early-returns
        // unless _health < 0.5f, so healthy writes are no-ops.
    }
}
